    # Check if the string is empty or has odd length (invalid)
    if len(string) % 2 != 0:
        return False

    # Stack to keep track of opening brackets
    stack = []

    # Flag to check if we've seen any nested structure
    has_nested = False

    for char in string:
        if char == '[':
            stack.append(char)
        elif char == ']':
            if not stack:
                return False  # Unmatched closing bracket
            stack.pop()
            # If we have more than one opening bracket in the stack, we have nesting
            if len(stack) >= 1:
                has_nested = True

    # Valid if all brackets are matched and there's at least one nesting
    return len(stack) == 0 and has_nested
